using System;
using System.Reflection;
using System.Linq;

// Also check the abstractions package
var files = new[] {
    "/home/runner/.nuget/packages/microsoft.agents.ai/1.11.1/lib/net9.0/Microsoft.Agents.AI.dll",
    "/home/runner/.nuget/packages/microsoft.agents.ai.abstractions/1.11.1/lib/net9.0/Microsoft.Agents.AI.Abstractions.dll"
};
