    foreach (var t in asm.GetExportedTypes().Where(t => t.Name.Contains("Session") || t.Name.Contains("AgentResponse")).OrderBy(t => t.FullName))
    {
        Console.WriteLine($"  {t.FullName} (Abstract={t.IsAbstract})");
        foreach (var c in t.GetConstructors(BindingFlags.Public | BindingFlags.Instance))
            Console.WriteLine($"    C: ({string.Join(", ", c.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name))})");
        foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
            Console.WriteLine($"    P: {p.Name} : {p.PropertyType.Name}");
        foreach (var m in t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly | BindingFlags.Static).Where(m => !m.IsSpecialName))
            Console.WriteLine($"    M: {m.Name}({string.Join(", ", m.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name))})");
    }
}
EOF
