using System.ComponentModel;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// ---------------------------------------------------------------------------
// Services
// ---------------------------------------------------------------------------
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddSingleton(new OpenAIClient(apiKey));

services.AddChatClient(builder => builder
    .UseLogging()
    .UseFunctionInvocation()
    .UseOpenAIChatClient(modelId));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new ResearchNotebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        WebSearchTool.SearchAsync,
        "web_search",
        "Searches the web for a query and returns a list of result snippets with URLs."),

    AIFunctionFactory.Create(
        ([Description("The title of the note")] string title,
         [Description("The content to save")] string content) =>
        {
            notebook.AddNote(title, content);
            return $"Note '{title}' saved.";
        },
        "save_note",
        "Saves a research note to the notebook for later summarization."),

    AIFunctionFactory.Create(
        () => notebook.GetAllNotes(),
        "get_notes",
        "Retrieves all saved research notes."),
};

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------
var agentOptions = new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An AI research agent that searches the web and takes notes.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [.. tools],
    },
};

var agent = new ChatClientAgent(chatClient, agentOptions, loggerFactory, sp);
var session = await agent.CreateSessionAsync();

// ---------------------------------------------------------------------------
// Main loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════════╗");
Console.WriteLine("║        🔍  AI Research Agent                ║");
Console.WriteLine("║  Enter a topic to research, or 'quit'.      ║");
Console.WriteLine("╚══════════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Topic> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
        continue;

    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var prompt = $"""
        Research the following topic by searching the web multiple times with different
        queries to get a well-rounded view. For each useful result, save a note with
        the key findings. After gathering enough information (at least 3 searches),
        retrieve all your notes and produce a comprehensive summary.

        Topic: {topic}
        """;

    Console.WriteLine("\n⏳ Researching...\n");

    try
    {
        var response = await agent.RunAsync(prompt, session);
        Console.WriteLine("── Summary ─────────────────────────────────────");
        Console.WriteLine(response.Text);
        Console.WriteLine("────────────────────────────────────────────────\n");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"❌ Error: {ex.Message}\n");
    }
}

Console.WriteLine("Goodbye!");

// ═══════════════════════════════════════════════════════════════════════════
// Supporting types
// ═══════════════════════════════════════════════════════════════════════════

/// <summary>
/// Simulated web search tool. In production, replace with a real search API
/// (e.g., Bing Search API, Google Custom Search).
/// </summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        Timeout = TimeSpan.FromSeconds(10),
    };

    public static async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        // Uses DuckDuckGo Instant Answer API (free, no key required).
        // Returns abstract + related topics as search snippets.
        try
        {
            var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
            var doc = await s_http.GetFromJsonAsync<JsonElement>(url);

            var results = new StringBuilder();

            var abstractText = doc.GetProperty("AbstractText").GetString();
            var abstractSource = doc.GetProperty("AbstractSource").GetString();
            var abstractUrl = doc.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.AppendLine($"[{abstractSource}] ({abstractUrl})");
                results.AppendLine(abstractText);
                results.AppendLine();
            }

            if (doc.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var topic in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var link = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.AppendLine($"• {text}");
                        if (!string.IsNullOrWhiteSpace(link))
                            results.AppendLine($"  URL: {link}");
                        results.AppendLine();
                        count++;
                    }
                }
            }

            return results.Length > 0
                ? results.ToString()
                : "No results found. Try a different or more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>In-memory notebook for collecting research notes.</summary>
sealed class ResearchNotebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public void AddNote(string title, string content)
        => _notes.Add((title, content, DateTime.UtcNow));

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var (t, c, ts) = _notes[i];
            sb.AppendLine($"--- Note {i + 1}: {t} ({ts:HH:mm:ss UTC}) ---");
            sb.AppendLine(c);
            sb.AppendLine();
        }
        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

