using System.ComponentModel;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// ---------------------------------------------------------------------------
// Services
// ---------------------------------------------------------------------------
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddSingleton(new OpenAIClient(apiKey));

services.AddChatClient(builder => builder
    .UseLogging()
    .UseFunctionInvocation()
    .UseOpenAIChatClient(modelId));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new ResearchNotebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        WebSearchTool.SearchAsync,
        "web_search",
        "Searches the web for a query and returns a list of result snippets with URLs."),

    AIFunctionFactory.Create(
        ([Description("The title of the note")] string title,
         [Description("The content to save")] string content) =>
        {
            notebook.AddNote(title, content);
            return $"Note '{title}' saved.";
        },
        "save_note",
        "Saves a research note to the notebook for later summarization."),

    AIFunctionFactory.Create(
        () => notebook.GetAllNotes(),
        "get_notes",
        "Retrieves all saved research notes."),
};

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------
var agentOptions = new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An AI research agent that searches the web and takes notes.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [.. tools],
    },
};

var agent = new ChatClientAgent(chatClient, agentOptions, loggerFactory, sp);
var session = await agent.CreateSessionAsync();

// ---------------------------------------------------------------------------
// Main loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════════╗");
Console.WriteLine("║        🔍  AI Research Agent                ║");
Console.WriteLine("║  Enter a topic to research, or 'quit'.      ║");
Console.WriteLine("╚══════════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Topic> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
        continue;

    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var prompt = $"""
        Research the following topic by searching the web multiple times with different
        queries to get a well-rounded view. For each useful result, save a note with
        the key findings. After gathering enough information (at least 3 searches),
        retrieve all your notes and produce a comprehensive summary.

        Topic: {topic}
        """;

    Console.WriteLine("\n⏳ Researching...\n");

    try
    {
        var response = await agent.RunAsync(prompt, session);
        Console.WriteLine("── Summary ─────────────────────────────────────");
        Console.WriteLine(response.Text);
        Console.WriteLine("────────────────────────────────────────────────\n");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"❌ Error: {ex.Message}\n");
    }
}

Console.WriteLine("Goodbye!");

