1. using System.ComponentModel;
2. using System.Net.Http.Json;
3. using System.Text;
4. using System.Text.Json;
5. using Microsoft.Extensions.AI;
6. using Microsoft.Extensions.DependencyInjection;
7. using Microsoft.Extensions.Logging;
8. using Microsoft.Agents.AI;
9. using OpenAI;
10. 
11. // ---------------------------------------------------------------------------
12. // Configuration
13. // ---------------------------------------------------------------------------
14. var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
15.     ?? throw new InvalidOperationException(
16.         "Set the OPENAI_API_KEY environment variable before running.");
17. 
18. const string modelId = "gpt-4o-mini-2024-07-18";
19. 
20. // ---------------------------------------------------------------------------
21. // Services
22. // ---------------------------------------------------------------------------
23. var services = new ServiceCollection();
24. 
25. services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
26. 
27. services.AddChatClient(sp => new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
28.     .UseFunctionInvocation();
29. 
30. var sp = services.BuildServiceProvider();
31. var chatClient = sp.GetRequiredService<IChatClient>();
32. var loggerFactory = sp.GetRequiredService<ILoggerFactory>();
33. 
34. // ---------------------------------------------------------------------------
35. // Tools
36. // ---------------------------------------------------------------------------
37. var notebook = new ResearchNotebook();
38. 
39. var tools = new AITool[]
40. {
41.     AIFunctionFactory.Create(
42.         WebSearchTool.SearchAsync,
43.         "web_search",
44.         "Searches the web for a query and returns a list of result snippets with URLs."),
45. 
46.     AIFunctionFactory.Create(
47.         ([Description("The title of the note")] string title,
48.          [Description("The content to save")] string content) =>
49.         {
50.             notebook.AddNote(title, content);
51.             return $"Note '{title}' saved.";
52.         },
53.         "save_note",
54.         "Saves a research note to the notebook for later summarization."),
55. 
56.     AIFunctionFactory.Create(
57.         () => notebook.GetAllNotes(),
58.         "get_notes",
59.         "Retrieves all saved research notes."),
60. };
61. 
62. // ---------------------------------------------------------------------------
63. // Agent
64. // ---------------------------------------------------------------------------
65. var agentOptions = new ChatClientAgentOptions
66. {
67.     Name = "ResearchAgent",
68.     Description = "An AI research agent that searches the web and takes notes.",
69.     ChatOptions = new ChatOptions
70.     {
71.         Temperature = 0f,
72.         MaxOutputTokens = 2048,
73.         Tools = [.. tools],
74.     },
75. };
76. 
77. var agent = new ChatClientAgent(chatClient, agentOptions, loggerFactory, sp);
78. var session = await agent.CreateSessionAsync();
79. 
80. // ---------------------------------------------------------------------------
81. // Main loop
82. // ---------------------------------------------------------------------------
83. Console.WriteLine("╔══════════════════════════════════════════════╗");
84. Console.WriteLine("║        🔍  AI Research Agent                ║");
85. Console.WriteLine("║  Enter a topic to research, or 'quit'.      ║");
86. Console.WriteLine("╚══════════════════════════════════════════════╝");
87. Console.WriteLine();
88. 
89. while (true)
90. {
91.     Console.Write("Topic> ");
92.     var topic = Console.ReadLine()?.Trim();
93. 
94.     if (string.IsNullOrEmpty(topic))
95.         continue;
96. 
97.     if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
98.         break;
99. 
100.     notebook.Clear();
101. 
102.     var prompt = $"""
103.         Research the following topic by searching the web multiple times with different
104.         queries to get a well-rounded view. For each useful result, save a note with
105.         the key findings. After gathering enough information (at least 3 searches),
106.         retrieve all your notes and produce a comprehensive summary.
107. 
108.         Topic: {topic}
109.         """;
110. 
111.     Console.WriteLine("\n⏳ Researching...\n");
112. 
113.     try
114.     {
115.         var response = await agent.RunAsync(prompt, session);
116.         Console.WriteLine("── Summary ─────────────────────────────────────");
117.         Console.WriteLine(response.Text);
118.         Console.WriteLine("────────────────────────────────────────────────\n");
119.     }
120.     catch (Exception ex)
121.     {
122.         Console.WriteLine($"❌ Error: {ex.Message}\n");
123.     }
124. }
125. 
126. Console.WriteLine("Goodbye!");
127. 
128. // ═══════════════════════════════════════════════════════════════════════════
129. // Supporting types
130. // ═══════════════════════════════════════════════════════════════════════════
131. 
132. /// <summary>
133. /// Simulated web search tool. In production, replace with a real search API
134. /// (e.g., Bing Search API, Google Custom Search).
135. /// </summary>
136. static class WebSearchTool
137. {
138.     private static readonly HttpClient s_http = new()
139.     {
140.         Timeout = TimeSpan.FromSeconds(10),
141.     };
142. 
143.     public static async Task<string> SearchAsync(
144.         [Description("The search query")] string query)
145.     {
146.         // Uses DuckDuckGo Instant Answer API (free, no key required).
147.         // Returns abstract + related topics as search snippets.
148.         try
149.         {
150.             var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
151.             var doc = await s_http.GetFromJsonAsync<JsonElement>(url);
152. 
153.             var results = new StringBuilder();
154. 
155.             var abstractText = doc.GetProperty("AbstractText").GetString();
156.             var abstractSource = doc.GetProperty("AbstractSource").GetString();
157.             var abstractUrl = doc.GetProperty("AbstractURL").GetString();
158.             if (!string.IsNullOrWhiteSpace(abstractText))
159.             {
160.                 results.AppendLine($"[{abstractSource}] ({abstractUrl})");
161.                 results.AppendLine(abstractText);
162.                 results.AppendLine();
163.             }
164. 
165.             if (doc.TryGetProperty("RelatedTopics", out var topics))
166.             {
167.                 var count = 0;
